public final class ApiTest {
    private ApiTest() {}

    public static void main(String[] args) {
        try {
            String grid_png = "/Users/clockorangezoe/Documents/phd_projects/code/geoAI/GRAIL_thumbnailator_B2/experiments/external/thumbnailator/source/src/test/resources/Thumbnailator/grid.png";
    String grid_jpeg = "/Users/clockorangezoe/Documents/phd_projects/code/geoAI/GRAIL_thumbnailator_B2/experiments/external/thumbnailator/source/src/test/resources/Thumbnailator/grid.jpg";
    String exif_jpeg = "/Users/clockorangezoe/Documents/phd_projects/code/geoAI/GRAIL_thumbnailator_B2/experiments/external/thumbnailator/source/src/test/resources/Exif/original.jpg";
    String output_dir = "/Users/clockorangezoe/Documents/phd_projects/code/geoAI/GRAIL_thumbnailator_B2/experiments/external/thumbnailator/.aideal_exec/B2/output";

    // pre-loaded typed inputs (comprehension.execute.preamble)
    BufferedImage sourceImage = new BufferedImage(32, 24, BufferedImage.TYPE_INT_RGB);
    Graphics2D graphics = sourceImage.createGraphics();
    graphics.setColor(Color.BLUE);
    graphics.fillRect(0, 0, 32, 24);
    graphics.setColor(Color.YELLOW);
    graphics.fillRect(8, 6, 16, 12);
    graphics.dispose();
    BufferedImage destinationImage = new BufferedImage(16, 12, BufferedImage.TYPE_INT_RGB);
    ByteArrayOutputStream imageBytes = new ByteArrayOutputStream();
    Path outputPath = Paths.get(output_dir, "thumbnail.png");
    Files.createDirectories(outputPath.getParent());

            // TODO API_TEST_START
            java.io.File destDir = outputPath.toFile();
            destDir.mkdirs();

            java.util.List<java.io.File> inputFiles = java.util.Arrays.asList(
                new java.io.File(grid_png), 
                new java.io.File(grid_jpeg)
            );

            java.util.List<java.io.File> resultFiles;
            try {
                resultFiles = net.coobird.thumbnailator.Thumbnails.fromFiles(inputFiles)
                    .size(200, 200)
                    .asFiles(destDir, net.coobird.thumbnailator.name.Rename.PREFIX_HYPHEN_THUMBNAIL);
            } catch (java.io.IOException e) {
                throw new RuntimeException("Failed to process and save thumbnails", e);
            }

            assert resultFiles != null && resultFiles.size() == 2 : "Expected exactly 2 files to be created";

            java.io.File firstFile = resultFiles.get(0);
            assert firstFile.exists() : "Output file should exist on disk";
            assert firstFile.getParentFile().getAbsoluteFile().equals(destDir.getAbsoluteFile()) : "Output file should be located in the destination directory";
            assert firstFile.getName().startsWith("thumbnail-") : "Output file should have the correct rename prefix";

            java.awt.image.BufferedImage resized;
            try {
                resized = javax.imageio.ImageIO.read(firstFile);
            } catch (java.io.IOException e) {
                throw new RuntimeException("Failed to read the generated thumbnail", e);
            }

            assert resized != null : "Generated thumbnail could not be decoded";
            assert resized.getWidth() <= 200 && resized.getHeight() <= 200 : "Image should be resized to fit within 200x200 bounding box";

            System.out.println("__CHECK__ asFiles " + resultFiles.size() + " files, first: " + firstFile.getName());
            // TODO API_TEST_END
            System.out.println("__DONE__");
        } catch (Throwable exc) {
            System.err.println("__RUN_ERR__ " + exc.getClass().getSimpleName()
                    + ": " + exc.getMessage());
            exc.printStackTrace(System.err);
            System.exit(1);
        }
    }
}
